import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

export const Globe: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const container = containerRef.current;
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, container.clientWidth / container.clientHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });

    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    container.appendChild(renderer.domElement);

    // Create a stylized globe
    const geometry = new THREE.SphereGeometry(5, 64, 64);
    const material = new THREE.MeshPhongMaterial({
      color: 0x111111,
      transparent: true,
      opacity: 0.9,
      wireframe: true,
    });
    const globe = new THREE.Mesh(geometry, material);
    scene.add(globe);

    // Add a points-based outer shell for "global" feel
    const pointsGeometry = new THREE.SphereGeometry(5.1, 48, 48);
    const pointsMaterial = new THREE.PointsMaterial({
      color: 0x64748b,
      size: 0.05,
    });
    const points = new THREE.Points(pointsGeometry, pointsMaterial);
    scene.add(points);

    // Add highlighted points for key regions
    const createMarker = (lat: number, lon: number, color: number) => {
      const phi = (90 - lat) * (Math.PI / 180);
      const theta = (lon + 180) * (Math.PI / 180);
      const radius = 5.1;

      const x = -(radius * Math.sin(phi) * Math.cos(theta));
      const z = (radius * Math.sin(phi) * Math.sin(theta));
      const y = (radius * Math.cos(phi));

      const markerGeom = new THREE.SphereGeometry(0.15, 16, 16);
      const markerMat = new THREE.MeshBasicMaterial({ color });
      const marker = new THREE.Mesh(markerGeom, markerMat);
      marker.position.set(x, y, z);

      // Add a glow effect
      const glowGeom = new THREE.SphereGeometry(0.3, 16, 16);
      const glowMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.3 });
      const glow = new THREE.Mesh(glowGeom, glowMat);
      glow.position.set(x, y, z);

      return { marker, glow };
    };

    // Region Coordinates (Approximate)
    const regions = [
      { name: 'GCC', lat: 24, lon: 45, color: 0xE2FF00 },
      { name: 'Europe', lat: 50, lon: 10, color: 0xE2FF00 },
      { name: 'SE Asia', lat: 15, lon: 100, color: 0xE2FF00 },
      { name: 'Africa', lat: 0, lon: 20, color: 0xE2FF00 }
    ];

    regions.forEach(r => {
      const { marker, glow } = createMarker(r.lat, r.lon, r.color);
      scene.add(marker);
      scene.add(glow);
    });

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);
    const pointLight = new THREE.PointLight(0xffffff, 1);
    pointLight.position.set(10, 10, 10);
    scene.add(pointLight);

    camera.position.z = 12;

    // Animation
    const animate = () => {
      requestAnimationFrame(animate);
      globe.rotation.y += 0.002;
      points.rotation.y += 0.002;

      // Rotate markers with the globe
      scene.children.forEach(child => {
        if (child instanceof THREE.Mesh && child !== globe) {
          const axis = new THREE.Vector3(0, 1, 0);
          child.position.applyAxisAngle(axis, 0.002);
        }
      });

      renderer.render(scene, camera);
    };

    animate();

    const handleResize = () => {
      if (!container) return;
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(container.clientWidth, container.clientHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      container.removeChild(renderer.domElement);
      geometry.dispose();
      material.dispose();
      renderer.dispose();
    };
  }, []);

  return (
    <div 
      ref={containerRef} 
      className="w-full h-[400px] md:h-[600px] cursor-grab active:cursor-grabbing"
      aria-label="3D Global Reach Visualization"
    />
  );
};

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

export const Globe: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const container = containerRef.current;
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, container.clientWidth / container.clientHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });

    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    container.appendChild(renderer.domElement);

    // Function to create text texture for labels
    const createTextTexture = (text: string) => {
      const canvas = document.createElement('canvas');
      const context = canvas.getContext('2d');
      if (!context) return null;

      canvas.width = 256;
      canvas.height = 64;

      context.font = 'Bold 32px Inter, Arial';
      context.fillStyle = '#E2FF00';
      context.textAlign = 'center';
      context.textBaseline = 'middle';
      context.fillText(text, 128, 32);

      const texture = new THREE.CanvasTexture(canvas);
      return texture;
    };

    // Create a stylized globe
    const geometry = new THREE.SphereGeometry(5, 64, 64);
    const material = new THREE.MeshPhongMaterial({
      color: 0x111111,
      transparent: true,
      opacity: 0.9,
      wireframe: true,
    });
    const globe = new THREE.Mesh(geometry, material);
    scene.add(globe);

    // Add a points-based outer shell for "global" feel
    const pointsGeometry = new THREE.SphereGeometry(5.1, 48, 48);
    const pointsMaterial = new THREE.PointsMaterial({
      color: 0x64748b,
      size: 0.05,
    });
    const points = new THREE.Points(pointsGeometry, pointsMaterial);
    scene.add(points);

    // Group to hold all revolving elements (markers and labels)
    const markerGroup = new THREE.Group();
    scene.add(markerGroup);

    // Add highlighted points for key regions
    const createMarker = (lat: number, lon: number, color: number, name: string) => {
      const phi = (90 - lat) * (Math.PI / 180);
      const theta = (lon + 180) * (Math.PI / 180);
      const radius = 5.1;

      const x = -(radius * Math.sin(phi) * Math.cos(theta));
      const z = (radius * Math.sin(phi) * Math.sin(theta));
      const y = (radius * Math.cos(phi));

      const markerGeom = new THREE.SphereGeometry(0.15, 16, 16);
      const markerMat = new THREE.MeshBasicMaterial({ color });
      const marker = new THREE.Mesh(markerGeom, markerMat);
      marker.position.set(x, y, z);

      // Add a glow effect
      const glowGeom = new THREE.SphereGeometry(0.3, 16, 16);
      const glowMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.3 });
      const glow = new THREE.Mesh(glowGeom, glowMat);
      glow.position.set(x, y, z);

      // Add Label Sprite
      const texture = createTextTexture(name);
      if (texture) {
        const spriteMaterial = new THREE.SpriteMaterial({ map: texture, transparent: true });
        const sprite = new THREE.Sprite(spriteMaterial);
        // Position sprite slightly above the marker
        sprite.position.set(x * 1.1, y * 1.1, z * 1.1);
        sprite.scale.set(1.5, 0.375, 1);
        markerGroup.add(sprite);
      }

      markerGroup.add(marker);
      markerGroup.add(glow);
    };

    // Region Coordinates
    const regions = [
      { name: 'GCC', lat: 24, lon: 45, color: 0xE2FF00 },
      { name: 'EUROPE', lat: 50, lon: 10, color: 0xE2FF00 },
      { name: 'SE ASIA', lat: 15, lon: 100, color: 0xE2FF00 },
      { name: 'AFRICA', lat: 0, lon: 20, color: 0xE2FF00 }
    ];

    regions.forEach(r => {
      createMarker(r.lat, r.lon, r.color, r.name);
    });

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);
    const pointLight = new THREE.PointLight(0xffffff, 1);
    pointLight.position.set(10, 10, 10);
    scene.add(pointLight);

    camera.position.z = 12;

    // Animation
    const animate = () => {
      requestAnimationFrame(animate);
      globe.rotation.y += 0.002;
      points.rotation.y += 0.002;
      markerGroup.rotation.y += 0.002;

      renderer.render(scene, camera);
    };

    animate();

    const handleResize = () => {
      if (!container) return;
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(container.clientWidth, container.clientHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      container.removeChild(renderer.domElement);
      geometry.dispose();
      material.dispose();
      renderer.dispose();
    };
  }, []);

  return (
    <div 
      ref={containerRef} 
      className="w-full h-[400px] md:h-[600px] cursor-grab active:cursor-grabbing"
      aria-label="3D Global Reach Visualization"
    />
  );
};

import React, { useState, useEffect } from 'react';
import { NavItem } from '../types';

interface NavbarProps {
  onNavigate: (page: 'home' | 'services') => void;
  currentPage: 'home' | 'services';
}

export const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentPage }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNavClick = (href: string) => {
    if (href === 'services') {
      onNavigate('services');
    } else {
      onNavigate('home');
      // If it's a section on home, allow standard anchor behavior if needed
      // but here we just switch to home
    }
    setIsMobileMenuOpen(false);
  };

  const navColorClass = isScrolled || currentPage === 'services' ? 'text-slate-900' : 'text-white';
  const navBgClass = isScrolled || currentPage === 'services' ? 'bg-white shadow-md py-3' : 'bg-transparent py-6';
  const logoFilterClass = !isScrolled && currentPage === 'home' ? 'brightness-0 invert' : '';

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${navBgClass}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <button onClick={() => onNavigate('home')} className="flex items-center">
          <img 
            src="assets/logo.png" 
            alt="Divyana Operations & Solutions" 
            className={`h-8 md:h-12 w-auto object-contain transition-all duration-300 ${logoFilterClass}`}
          />
        </button>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center space-x-8">
          <button
            onClick={() => handleNavClick('services')}
            className={`text-sm font-medium transition-colors hover:opacity-70 ${navColorClass}`}
          >
            Service
          </button>
          <a
            href={currentPage === 'home' ? '#about' : '/#about'}
            onClick={() => currentPage !== 'home' && onNavigate('home')}
            className={`text-sm font-medium transition-colors hover:opacity-70 ${navColorClass}`}
          >
            About Us
          </a>
          <a
            href={currentPage === 'home' ? '#contact' : '/#contact'}
            onClick={() => currentPage !== 'home' && onNavigate('home')}
            className={`text-sm font-medium transition-colors hover:opacity-70 ${navColorClass}`}
          >
            Contact Us
          </a>
          <button className="bg-black text-white px-6 py-2.5 rounded-full text-sm font-semibold hover:bg-slate-800 transition-all">
            Be Our Partner
          </button>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden p-2"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
